            { name: 'Auto-sizing', code: '<form class="row gy-2 gx-3 align-items-center">\n  <div class="col-auto">\n    <label class="visually-hidden" for="autoSizingInput">Name</label>\n    <input type="text" class="form-control" id="autoSizingInput" placeholder="Jane Doe">\n  </div>\n  <div class="col-auto">\n    <button type="submit" class="btn btn-primary">Submit</button>\n  </div>\n</form>', description: 'Auto-size columns based on content width', preview: '<div style="display: flex; gap: 0.5rem; align-items: center;"><input type="text" placeholder="Jane Doe" style="padding: 0.375rem 0.75rem; border: 1px solid #dee2e6; border-radius: 0.375rem; width: auto;"><select style="padding: 0.375rem 2rem 0.375rem 0.75rem; border: 1px solid #dee2e6; border-radius: 0.375rem;"><option>Choose...</option><option>One</option></select><button style="padding: 0.375rem 0.75rem; background: #0d6efd; color: white; border: none; border-radius: 0.375rem;">Submit</button></div>' },
            { name: 'Inline Forms', code: '<form class="row row-cols-lg-auto g-3 align-items-center">\n  <div class="col-12">\n    <input type="text" class="form-control" placeholder="Username">\n  </div>\n  <div class="col-12">\n    <button type="submit" class="btn btn-primary">Submit</button>\n  </div>\n</form>', description: 'Create compact inline forms', preview: '<div style="display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap;"><div style="display: flex; align-items: center; gap: 0.25rem;"><span style="padding: 0.375rem 0.75rem; background: #e9ecef; border: 1px solid #dee2e6; border-radius: 0.375rem 0 0 0.375rem; border-right: 0;">@</span><input type="text" placeholder="Username" style="padding: 0.375rem 0.75rem; border: 1px solid #dee2e6; border-radius: 0 0.375rem 0.375rem 0;"></div><label style="display: flex; align-items: center; gap: 0.25rem;"><input type="checkbox" style="accent-color: #0d6efd;"><span style="font-size: 0.875rem;">Remember me</span></label><button style="padding: 0.375rem 0.75rem; background: #0d6efd; color: white; border: none; border-radius: 0.375rem;">Submit</button></div>' }
